namespace sv_e9ce2280d34d4717a480b916962bfb1b.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

namespace sv_e9ce2280d34d4717a480b916962bfb1b.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, basil, and tomato sauce.", 25),
            new(2, "Risotto alla Milanese", "Creamy saffron-infused risotto from Milan.", 40),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream.", 30),
            new(4, "Pasta Carbonara", "Roman pasta with egg, pecorino, guanciale, and black pepper.", 20),
        },
        [2] = new List<Recipe>
        {
            new(5, "Kung Pao Chicken", "Spicy stir-fried chicken with peanuts, vegetables, and chili peppers.", 35),
            new(6, "Mapo Tofu", "Silken tofu in a fiery Sichuan chili and bean paste sauce.", 25),
            new(7, "Xiaolongbao", "Steamed soup dumplings filled with pork and rich broth.", 60),
            new(8, "Char Siu", "Cantonese-style barbecued pork with a sweet glaze.", 50),
        },
        [3] = new List<Recipe>
        {
            new(9, "Tacos al Pastor", "Spit-grilled pork tacos with pineapple, cilantro, and onion.", 45),
            new(10, "Guacamole", "Fresh avocado dip with lime, cilantro, and jalapeño.", 10),
            new(11, "Mole Poblano", "Complex sauce with chocolate, chilies, and spices served over chicken.", 90),
            new(12, "Elote", "Grilled Mexican street corn with mayo, cotija cheese, and chili powder.", 15),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_e9ce2280d34d4717a480b916962bfb1b.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _error;
    private int _loadedCuisineId;

    private CancellationTokenSource? _cts;
    private readonly CancellationTokenSource _disposalCts = new();

    private IEnumerable<Recipe> DisplayRecipes =>
        Sort?.ToLowerInvariant() switch
        {
            "newest" => _recipes!.OrderByDescending(r => r.Id),
            "popular" => _recipes!.OrderBy(r => r.PrepTimeMinutes),
            _ => _recipes!
        };

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            // Only sort changed — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for the previous cuisine.
        await CancelPendingRequestAsync();

        _error = null;
        _isRefreshing = _recipes is not null;

        _cts = CancellationTokenSource.CreateLinkedTokenSource(_disposalCts.Token);

        try
        {
            var token = _cts.Token;
            var results = await RecipeService.GetByCuisineAsync(CuisineId, token);

            token.ThrowIfCancellationRequested();

            _recipes = results;
            _loadedCuisineId = CuisineId;
        }
        catch (OperationCanceledException) when (_disposalCts.IsCancellationRequested)
        {
            // Component is being disposed — do nothing.
        }
        catch (OperationCanceledException)
        {
            // Request was superseded by a newer navigation — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _disposalCts.Cancel();
        _disposalCts.Dispose();
        _cts?.Dispose();
    }
}

